test("Studio admission preserves replay, cancellation and tenant/day accounting", () => {
  const dispatch = planner(readCatalog());
  const request = book("first", 7);
  assert.deepEqual(dispatch(request), {status:"booked", id:"first", remaining:1});
  assert.deepEqual(dispatch(request), {status:"replay", id:"first"});
  assert.equal(dispatch({...request, units:6}).status, "conflict");
  assert.deepEqual(dispatch(book("overflow", 2)), {status:"full", id:"overflow", remaining:1});
  assert.equal(dispatch(book("last", 1)).status, "booked");
  assert.equal(dispatch(book("another-day", 8, {day:"2025-04-03"})).status, "booked");
  assert.equal(dispatch(book("fallback-full", 6, {tenant:"iris"})).status, "full");
  assert.equal(dispatch(book("fallback", 5, {tenant:"iris"})).status, "booked");
  assert.equal(dispatch(book("archive-full", 6, {service:"archive"})).status, "full");
  assert.equal(dispatch(book("archive", 5, {service:"archive"})).status, "booked");
  assert.equal(dispatch({service:"studio", action:"cancel", id:"first"}).status, "cancelled");
  assert.equal(dispatch({service:"studio", action:"cancel", id:"first"}).status, "replay");
  assert.equal(dispatch(request).status, "cancelled");
  assert.equal(dispatch(book("replacement", 7)).status, "booked");
  assert.deepEqual(dispatch({service:"studio", action:"usage", tenant:"orchid", day:date}), {units:8});
  assert.equal(planner(readCatalog())(book("fresh", 8)).status, "booked");
});

test("renewals inherit the tenant and use Studio admission with normal replay semantics", () => {
  const dispatch = planner(readCatalog());
  dispatch(book("original", 7));
  const renewal = {service:"studio", action:"renew", previous:"original", id:"renewed",
    day:"2025-05-02", tenant:"iris"};
  assert.deepEqual(dispatch(renewal), {status:"booked", id:"renewed", remaining:1});
  assert.equal(dispatch(renewal).status, "replay");
  assert.equal(dispatch({...renewal, units:6}).status, "conflict");
  assert.equal(dispatch({...renewal, id:"too-much", units:2}).status, "full");
  assert.equal(dispatch({...renewal, id:"last-unit", units:1}).status, "booked");
  dispatch({service:"studio", action:"cancel", id:"renewed"});
  assert.equal(dispatch(renewal).status, "cancelled");
  dispatch({service:"studio", action:"cancel", id:"original"});
  assert.deepEqual(dispatch({...renewal, id:"missing"}), {status:"missing", id:"original"});
  dispatch(book("iris", 5, {tenant:"iris"}));
  assert.equal(dispatch({...renewal, previous:"iris", id:"iris-next", units:6}).status, "full");
  dispatch(book("archive", 5, {service:"archive"}));
  assert.equal(dispatch({...renewal, service:"archive", previous:"archive", units:6}).status, "full");
});

